parameters.jsCode:
console.log('Webhook input:', $json);
const data = $json.body || {};

return [{
  json: {
    departureLocation: data.customAirport || data.departureLocation || "Not provided",
    destination: data.customDestination || data.destination || "Not specified",
    budget: data.budget || "~",
    tripType: data.tripType || "N/A",
    groupSize: data.groupSize || "1",
    ageRange: Array.isArray(data.ageRange) ? data.ageRange : (data.ageRange ? [data.ageRange] : ["~"]),
    dayActivity: Array.isArray(data.dayActivity) ? data.dayActivity : (data.dayActivity ? [data.dayActivity] : []),
    nightActivity: Array.isArray(data.nightActivity) ? data.nightActivity : (data.nightActivity ? [data.nightActivity] : []),
    startDate: data.startDate || "N/A",
    endDate: data.endDate || "N/A",
    email: data.email || "unknown"
  }
}];

const {
  destination,
  departureLocation,
  startDate,
  endDate,
  budget,
  tripType,
  groupSize,
  ageRange,
  dayActivity,
  nightActivity,
  email
} = $json;

return [{
  json: {
    email,
    destination,
    departureLocation,
    startDate,
    endDate,
    groupSize,
    budget,
    tripType,
    ageRange,
    dayActivity,
    nightActivity,
    prompt: `You are a helpful travel agent. A user is planning a tropical beach getaway and needs a detailed itinerary.

- Departure location: ${departureLocation || "Not provided"}
- Destination: ${destination}
- Travel dates: ${startDate} to ${endDate}
- Budget: $${budget}
- Trip type: ${tripType}
- Group size: ${groupSize}
- Age ranges: ${Array.isArray(ageRange) ? ageRange.join(", ") : ageRange || "not specified"}
- Preferred day activities: ${Array.isArray(dayActivity) ? dayActivity.join(", ") : dayActivity || "none"}
- Preferred night activities: ${Array.isArray(nightActivity) ? nightActivity.join(", ") : nightActivity || "none"}

Create a complete itinerary for this trip. Include recommendations for:
1. Flights (airlines and routes from ${departureLocation || "the nearest major airport"})
2. Accommodation options
3. Daily schedule with activities tailored to the preferred day and night activities
4. Local food spots
5. Transportation and travel tips

Respond in a clean and organized layout with sections.`
  }
}];

const travel = $node["Prepare Travel Data"].json;
const ai = $node["OpenAI"].json.message?.content || "No itinerary found.";

return [{
  json: {
    destination: travel.destination,
    departureLocation: travel.departureLocation,
    startDate: travel.startDate,
    endDate: travel.endDate,
    groupSize: travel.groupSize,
    budget: travel.budget,
    tripType: travel.tripType,
    ageRange: travel.ageRange,
    dayActivity: travel.dayActivity,
    nightActivity: travel.nightActivity,
    email: travel.email,
    itinerary: ai
  }
}];

// In-memory storage for itineraries
if (!global.itineraries) {
  global.itineraries = {};
}

const trip = $json;

// Generate a unique ID for this itinerary
const itineraryId = Date.now().toString();

// Store the itinerary data
global.itineraries[itineraryId] = {
  tripTitle: `🌍 Trip Plan: ${trip.destination}`,
  departure: trip.departureLocation,
  dates: `${trip.startDate} to ${trip.endDate}`,
  groupSize: trip.groupSize,
  budget: `$${trip.budget}`,
  tripType: trip.tripType,
  ageRange: Array.isArray(trip.ageRange) ? trip.ageRange.join(", ") : trip.ageRange,
  dayActivity: Array.isArray(trip.dayActivity) ? trip.dayActivity.join(", ") : trip.dayActivity || "None",
  nightActivity: Array.isArray(trip.nightActivity) ? trip.nightActivity.join(", ") : trip.nightActivity || "None",
  itinerary: trip.itinerary
};

// Return a redirect URL with the itinerary ID
return [{
  headers: {
    "Location": `http://localhost/travel/tropical_trip_itinerary.html?itineraryId=${itineraryId}`
  },
  statusCode: 302
}];

const itineraryId = $json.query.itineraryId;

if (!global.itineraries || !global.itineraries[itineraryId]) {
  return [{
    json: { error: 'Itinerary not found' },
    statusCode: 404
  }];
}

return [{
  json: global.itineraries[itineraryId]
}];
